L000452	\section{Appendix A: Noncommutative Fourier transformation}
L000453	Given an arbitrary target Hamiltonian, which, in the Fock basis $\{|n\rangle\}$, can be expressed as
L000454	\begin{equation}
L000455	\hat{H}_{\rm tar} =
L000456	
L000457	\sum_{n,m}h_{n,m}|n\rangle\langle m|,
L000458	\label{SMHtar}
L000459	\end{equation}
L000460	
L000461	where $h_{n,m}$ is the superposition coefficient determined by the target state. The Husimi Q-function of the target Hamiltonian can be readily obtained as
L000462	\begin{eqnarray}
L000463	H^{Q}_{\rm tar}(x,p)&=&\langle\alpha|\hat{H}_{\rm tar}|\alpha\rangle
L000464	=e^{-|\alpha|^{2}}\sum_{n,m}\sum_{n',m'}h_{n,m}\frac{(\alpha^{*})^{n'}\alpha^{m'}}{\sqrt{n'!m'!}}\langle n'|n\rangle\langle m|m'\rangle \nonumber\\
L000465	&=&e^{-|\alpha|^{2}}\sum_{n,m}h_{n,m}\frac{(\alpha^{*})^{n}\alpha^{m}}{\sqrt{n!m!}} \nonumber\\
L000466	&=&e^{-\frac{x^{2}+p^{2}}{2\lambda}}\sum_{n,m}h_{n,m}\frac{\left(\frac{x-ip}{\sqrt{2\lambda}}\right)^{n}\left(\frac{x+ip}{\sqrt{2\lambda}}\right)^{m}}{\sqrt{n!m!}},
L000467	\label{HusimiQ}
L000468	\end{eqnarray}
L000469	
L000470	where $|\alpha\rangle$ denotes the coherent state defined by $\hat{a}|\alpha\rangle=\alpha|\alpha\rangle$, with $\alpha=\left(x+ip\right)/\sqrt{2\lambda}$ and $\lambda$ the dimensionless Planck constant.
L000471	
L000472	By switching to polar coordinates with $x=r\cos{\theta}$ and $p=r\sin{\theta}$, and introducing $k_{x}=k\cos{\tau}=k\cos{\omega_{0}t}$ and $k_{p}=k\sin{\tau}=k\sin{\omega_{0}t}$, where $\omega_{0}$ is the resonance frequency of the cavity, the noncommutative Fourier coefficient corresponding to the target Hamiltonian [cf. Eq.~(3) in the main text] can be expressed as
L000473	\begin{equation}
L000474	f_{\rm tar}(k,\tau)=\frac{e^{\frac{\lambda}{4}k^{2}}}{2\pi}\int\int rdrd\theta H^{Q}_{\rm tar}(r\cos{\theta},r\sin{\theta})e^{-ikr\cos{(\theta-\tau)}}.
L000475	\label{fTdef}
L000476	\end{equation}
L000477	Under the Fock basis, each component of $f_{\rm tar}$ (i.e., each matrix element) can be derived as
L000478	\begin{eqnarray}
L000479	f_{n,m}(k,\tau)&=& \frac{\langle n|f_{\rm tar}(k,\tau)|m\rangle}{h_{n,m}} \nonumber\\
L000480	&=&\ \frac{e^{\frac{\lambda}{4}k^{2}}}{2\pi h_{n,m}}}\int_{0}^{+\infty}rdr\int_{0}^{2\pi}d\theta\langle n|H^{Q}_{\rm tar}(r\cos{\theta},r\sin{\theta})|m\rangle e^{-ikr\cos{(\theta-\tau)} \nonumber\\
L000481	&=&\frac{e^{\frac{\lambda}{4}k^{2}}}{2\pi}\frac{e^{i(m-n)\tau}}{\sqrt{n!m!}}\left(\frac{1}{\sqrt{2\lambda}}\right)^{n+m}\int_{0}^{+\infty}r^{n+m+1}e^{-\frac{r^{2}}{2\lambda}}dr\int_{0}^{2\pi}e^{-ikr\cos{(\theta-\tau)}}e^{i(m-n)(\theta-\tau)}d\theta \nonumber\\
L000482	&=&e^{\frac{\lambda}{4}k^{2}}\frac{e^{i(m-n)\tau}}{\sqrt{n!m!}}i^{n-m}\left(\frac{1}{\sqrt{2\lambda}}\right)^{n+m}\int_{0}^{+\infty}r^{n+m+1}e^{-\frac{r^{2}}{2\lambda}}J_{n-m}(-kr)dr \nonumber\\
L000483	&=&\left \{ \begin{array}{lll}
L000484	e^{\frac{\lambda}{4}k^{2}}\sqrt{\frac{n!}{m!}}\left(-ie^{i\tau}\frac{1}{k}\sqrt{\frac{2}{\lambda}}\right)^{m-n}\frac{\lambda}{\Gamma(1+n-m)}{}_{1}F_{1}(1+n; 1+n-m; -\frac{\lambda}{2}k^{2}), \quad n-m>-1, \\
L000485	e^{\frac{\lambda}{4}k^{2}}\sqrt{\frac{m!}{n!}}\left(-ie^{-i\tau}\frac{1}{k}\sqrt{\frac{2}{\lambda}}\right)^{n-m}\frac{\lambda}{\Gamma(1+m-n)}{}_{1}F_{1}(1+m; 1+m-n; -\frac{\lambda}{2}k^{2}), \quad n-m\leq -1.
L000486	\end{array} \right.
L000487	\label{fTcomponent}
L000488	\end{eqnarray}
L000489	Here, $J_{n-m}(z)$ is the Bessel function of the first kind (of order $n-m$), which satisfies the identity
L000490	\begin{equation}
L000491	J_{z}(x)=\frac{i^{-z}}{2\pi}\int_{0}^{2\pi}e^{i(zy+x\cos{y})}dy,
L000492	\end{equation}
L000493	$\Gamma(n)=(n-1)!$ is the Gamma function, and ${}_{1}F_{1}(a;b;z)$ is the Kummer confluent hypergeometric function. Note that, in the final step of Eq.~(\ref{fTcomponent}), we have classified the identity into two different situations for the convenience of numerical simulations. The entire noncommutative Fourier coefficient can be reconstructed as
L000494	\begin{equation}
L000495	f_{\rm tar}(k,\tau)=\sum_{n,m}h_{n,m}f_{n,m}(k,\tau).
L000496	\label{fTcomplete}
L000497	\end{equation}
L000498	The corresponding driving potential can then be obtained as~\cite{guo2024prl,LZGuo2025CP}
L000499	\begin{eqnarray}
L000500	\hat{V}(\hat{x},\tau) &=& \int_{-\infty}^{+\infty} \frac{|k|}{2} \beta_0 f_{\rm tar}(k, \tau) e^{ik\hat{x}} \, dk \nonumber\\
L000501	&=&\int_{0}^{+\infty}\beta_0 A(k,\tau)\cos{[k\hat{x}+\phi(k,\tau)]}dk,
L000502	\end{eqnarray}
L000503	where $\beta_0$ is a \emph{target-independent} parameter that controls the driving strength. The time-dependent amplitude $A(k,\tau)$ and phase $\phi(k,\tau)$ are given by
L000504	\begin{equation}
L000505	A(k,\tau)=k|f_{\rm tar}(k\cos{\tau},k\sin{\tau})|,\quad \phi(k,\tau)=\text{Arg}[f_{\rm tar}(k\cos{\tau},k\sin{\tau})].
L000506	\end{equation}
L000507	
L000508	
L000509	\section{Appendix B: Floquet Hamiltonian engineering}
L000510	To generate the target Hamiltonian $\hat{H}_{\rm tar}$, which is in general an arbitrary function of quadrature operators $\hat{x}$ and $\hat{p}$, we drive the cavity with a periodic external potential $\hat{V}(\hat{x},t)=V(\hat{x},t+T_d)$ with $T_d=2\pi/\omega_d$ and $\omega_d$ the driving frequency. The total Hamiltonian of the driven cavity is given by
L000511	\begin{equation}
L000512	\hat{H}_{\rm cav}(t)=\frac{\omega_0}{2}\left(\hat{x}^{2}+\hat{p}^{2}\right)+ \hat{V}(\hat{x},t).
L000513	\label{rampH}
L000514	\end{equation}
L000515	
L000516	To analyze the system dynamics, we transform the above Hamiltonian into a rotating frame at frequency $\Omega=2\pi/T$ with $T=nT_d $ $(n\in \mathbb{Z}^+)$. The quadrature operator $\hat{x}$ transforms under the unitary operator $\hat{O}(t)\equiv e^{i\hat{a}^\dagger\hat{a}\Omega t}$ as $\hat{O}(t)\hat{x}\hat{O}^\dagger(t)=\hat{x}\cos (\Omega t)+\hat{p}\sin (\Omega t)$, while the transformed Hamiltonian in the rotating frame becomes
L000517	\beqa\label{eq-Ht}
L000518	\hat{H}(t)&\equiv&\hat{O}(t)\hat{\mathcal{H}}(t)\hat{O}^\dagger(t)-i\lambda \hat{O}(t)\dot{\hat{O}}^\dagger(t)\nonumber \\
L000519	&=&\beta V\Big[\hat{x}\cos (\Omega t)+\hat{p}\sin (\Omega t),t\Big].
L000520	\eeqa
L000521	
L000522	Here,  we have employed the multiphoton resonance condition $T=2\pi/\omega_0$, or equivalently $\Omega=\omega_0$, such that the driving frequency is an integer multiple of the bare cavity frequency.
L000523	
L000524	A system subject to a periodic drive is commonly referred to as a \textit{Floquet system}~\cite{Shirley1965pr}. The Floquet theory states that the stroboscopic time evolution of such a system can be described by an effective time-independent Floquet Hamiltonian $\hat{H}_{\text F}$, which is defined by the relation~\cite{Shirley1965pr}
L000525	\beqa\label{eq-HFt0}
L000526	\exp\Big(-i\frac{1}{\lambda}\hat{H}_{\text F}T\Big)=\mathcal{T}\exp\Big[-i\frac{1}{\lambda}\int_{0}^{T}\hat{H}(t)dt\Big],
L000527	\eeqa
L000528	where $\mathcal{T}$ is the time-ordering operator.
L000529	
L000530	Under the rotating wave approximation (RWA), the Floquet Hamiltonian $\hat{H}_F$ can be well approximated by the time average of $\hat{H}(t)$ over one driving period $T$ ~\cite{guo2024prl,Eckardt2015NJP}, i.e.,
L000531	\beqa\label{eq-h0h1h3}
L000532	\lim_{\omega_0/\beta\rightarrow\infty}\hat{H}^{}_{\text F}(\hat{x},\hat{p})&=&\frac{1}{T}\int_{0}^{T}dt  \hat{H}(t).\ \ \
L000533	\eeqa
L000534	
L000535	By properly engineering the time-dependent driving potential $\hat{V}(\hat{x},t)$, one can realize a desired Floquet Hamiltonian $\hat{H}_{\text F}(\hat{x},\hat{p})$ that effectively implements the target Hamiltonian $\hat{H}_{\rm tar}(\hat{x},\hat{p})$.
